import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_forward_kernel(
    const float* input, const float* weight, const float* bias,
    int batch_size, int in_channels, int out_channels,
    int in_h, int in_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w,
    int groups,
    int out_h, int out_w,
    float* output
) {
    int oc = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int ow = blockIdx.z * blockDim.z + threadIdx.z;
    int n = blockIdx.w;

    if (n >= batch_size || oc >= out_channels || oh >= out_h || ow >= out_w)
        return;

    int group_size = out_channels / groups;
    int g = oc / group_size;
    int in_channels_per_group = in_channels / groups;

    float val = 0.0f;

    for (int ic = 0; ic < in_channels_per_group; ++ic) {
        for (int kh = 0; kh < kernel_h; ++kh) {
            for (int kw = 0; kw < kernel_w; ++kw) {
                int ih = oh * stride_h - pad_h + kh * dilation_h;
                int iw = ow * stride_w - pad_w + kw * dilation_w;

                if (ih >= 0 && ih < in_h && iw >= 0 && iw < in_w) {
                    int input_idx = n * in_channels * in_h * in_w +
                                  (g * in_channels_per_group + ic) * in_h * in_w +
                                  ih * in_w +
                                  iw;

                    int weight_idx = oc * (in_channels_per_group * kernel_h * kernel_w) +
                                   ic * (kernel_h * kernel_w) +
                                   kh * kernel_w +
                                   kw;

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias)
        val += bias[oc];

    int output_idx = n * out_channels * out_h * out_w +
                   oc * out_h * out_w +
                   oh * out_w +
                   ow;
    output[output_idx] = val;
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::IntArrayRef stride,
    torch::IntArrayRef padding,
    torch::IntArrayRef dilation,
    int groups
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_h = input.size(2);
    auto in_w = input.size(3);

    auto out_channels = weight.size(0);
    auto kernel_h = weight.size(2);
    auto kernel_w = weight.size(3);

    int pad_h = padding[0], pad_w = padding[1];
    int stride_h = stride[0], stride_w = stride[1];
    int dilation_h = dilation[0], dilation_w = dilation[1];

    int out_h = (in_h + 2 * pad_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    int out_w = (in_w + 2 * pad_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    dim3 block(16, 8, 4);
    dim3 grid(
        (out_channels + block.x - 1) / block.x,
        (out_h + block.y - 1) / block.y,
        (out_w + block.z - 1) / block.z
    );
    int grid_n = batch_size;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    conv2d_forward_kernel<<<grid, block, 0, stream>>>(
        input.contiguous().data_ptr<float>(),
        weight.contiguous().data_ptr<float>(),
        bias.defined() ? bias.contiguous().data_ptr<float>() : nullptr,
        batch_size,
        in_channels,
        out_channels,
        in_h,
        in_w,
        kernel_h,
        kernel_w,
        stride_h,
        stride_w,
        pad_h,
        pad_w,
        dilation_h,
        dilation_w,
        groups,
        out_h,
        out_w,
        output.data_ptr<float>()
    );

    return output;
}
"""

conv2d_cpp_source = "torch::Tensor conv2d_forward_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, torch::IntArrayRef stride, torch::IntArrayRef padding, torch::IntArrayRef dilation, int groups);"

conv2d_ext = load_inline(
    name="conv2d_ext",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            out_channels,
            in_channels // groups,
            kernel_size[0],
            kernel_size[1]
        ))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if self.bias is not None:
            nn.init.zeros_(self.bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv2d_ext.conv2d_forward_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.Tensor(),
            self.stride,
            self.padding,
            self.dilation,
            self.groups
        )
